```dart
import 'package:mad_flutter_practicum/app/app.dart';
import 'package:mad_flutter_practicum/domain/domain.dart';

import 'widgets/widgets.dart';

class CurrencyListPage extends StatefulWidget {
  const CurrencyListPage({super.key});

  @override
  State<CurrencyListPage> createState() => _CurrencyListPageState();
}

class _CurrencyListPageState extends State<CurrencyListPage> with SingleTickerProviderStateMixin {
  late final ValueNotifier<List<CurrencyModel>> _filteredCurrenciesNotifier;

  late final AnimationController _fadeController;

  late Future<List<CurrencyModel>> _currencyListFuture;

  List<CurrencyModel> _allCurrencies = [];
  int _nextPage = 1;
  bool _hasMore = true;
  bool _isLoadingMore = false;

  String _searchQuery = '';

  @override
  void initState() {
    super.initState();
    _initAnimation();
    _initData();
  }

  @override
  void dispose() {
    _filteredCurrenciesNotifier.dispose();
    _fadeController.dispose();
    super.dispose();
  }

  void _initAnimation() {
    _fadeController = AnimationController(
      duration: Duration(milliseconds: 400),
      vsync: this,
    );
  }

  void _initData() {
    final currencyRepository = context.read<CurrencyRepository>();

    _currencyListFuture = currencyRepository.fetchRates(const CurrencyPageRequest(base: 'USD', pageSize: 20)).then((CurrencyPage page) {
      setState(() {
        _allCurrencies = page.items;
        _nextPage = 1;
        _hasMore = page.hasMore;
      });
      _filteredCurrenciesNotifier = ValueNotifier(List.unmodifiable(_allCurrencies));

      _fadeController.forward();

      currencyRepository.saveCurrencyList(List.from(_allCurrencies));

      return _allCurrencies;
    });
  }

  Future<void> _loadMore() async {
    if (_isLoadingMore || !_hasMore) return;

    setState(() => _isLoadingMore = true);
    try {
      final repository = context.read<CurrencyRepository>();
      final page = await repository.fetchRates(CurrencyPageRequest(base: 'USD', pageSize: 20, page: _nextPage));
      if (page.items.isNotEmpty) {
        setState(() {
          _allCurrencies.addAll(page.items);
          _nextPage++;
        });
        _filteredCurrenciesNotifier.value = _applyFilter(_searchQuery, _allCurrencies);
      }
      setState(() => _hasMore = page.hasMore);
    } finally {
      if (mounted) setState(() => _isLoadingMore = false);
    }
  }

  static List<CurrencyModel> _applyFilter(String query, List<CurrencyModel> all) {
    final lowerQuery = query.toLowerCase();
    return all.where((currency) {
      return currency.name.toLowerCase().contains(lowerQuery) ||
             currency.symbol.toLowerCase().contains(lowerQuery);
    }).toList(growable: false);
  }

  void _filterCurrencies(String query) {
    _searchQuery = query;
    _filteredCurrenciesNotifier.value = _applyFilter(query, _allCurrencies);
  }

  Widget _buildLoadMoreButton() {
    if (!_hasMore || _isLoadingMore) return const SizedBox.shrink();

    return Align(
      alignment: Alignment.bottomCenter,
      child: Padding(
        padding: const EdgeInsets.only(bottom: 20),
        child: ElevatedButton(
          onPressed: _loadMore,
          child: Text(context.loc.showMore),
        ),
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: Text(context.loc.currencyRate)),
      body: FutureBuilder<List<CurrencyModel>>(
        future: _currencyListFuture,
        builder: (BuildContext context, AsyncSnapshot<List<CurrencyModel>> snapshot) {
          if (!snapshot.hasData) return const SizedBox.shrink();

          return FadeTransition(
            opacity: _fadeController.view,
            child: Column(
              children: [
                Padding(
                  padding: const EdgeInsets.symmetric(vertical: 10, horizontal: 22),
                  child: SearchView(onChanged: _filterCurrencies),
                ),
                Expanded(
                  child: ValueListenableBuilder<List<CurrencyModel>>(
                    valueListenable: _filteredCurrenciesNotifier,
                    builder: (BuildContext context, List<CurrencyModel> data, _) {
                      return ListView.builder(
                        itemCount: data.length,
                        itemBuilder: (BuildContext context, int index) {
                          final CurrencyModel currency = data[index];

                          return Padding(
                            key: ValueKey(currency.id),
                            padding: index == 0 ? const EdgeInsets.only(top: 20) : const EdgeInsets.only(top: 10),
                            child: CurrencyCard(model: currency),
                          );
                        },
                        padding: const EdgeInsets.fromLTRB(22, 0, 22, 40),
                      );
                    },
                  ),
                ),
                _isLoadingMore ? const Padding(
                  padding: EdgeInsets.all(16.0),
                  child: Center(child: CircularProgressIndicator()),
                ) : _buildLoadMoreButton(),
              ],
            ),
          );
        },
      ),
    );
  }
}
