  late final AnimationController _fadeController;

  List<CurrencyModel> _allCurrencies = [];
  int _nextPage = 1;
  bool _hasMore = true;
  bool _isFetchingMore = false;

  @override
  void initState() {
    super.initState();
    _initAnimation();
    _filteredCurrenciesNotifier = ValueNotifier([]);
    _loadFirstPage();
  }

  @override
  void dispose() {
    _filteredCurrenciesNotifier.dispose();
    _fadeController.dispose();
    super.dispose();
  }

  void _initAnimation() {
    _fadeController = AnimationController(
      duration: const Duration(milliseconds: 400),
      vsync: this,
    );
  }

  Future<void> _loadFirstPage() async {
    final repository = context.read<CurrencyRepository>();

    try {
      final page = await repository.fetchRates(const CurrencyPageRequest(
        base: 'USD',
        page: 0,
        pageSize: 20,
      ));

      setState(() {
        _allCurrencies = List.from(page.items);
        _nextPage = 1;
        _hasMore = page.hasMore;
      });

      _filteredCurrenciesNotifier.value = List.unmodifiable(_allCurrencies);

      repository.saveCurrencyList(List.from(_allCurrencies));

      if (mounted) {
        _fadeController.forward();
      }
    } catch (_) {
      // In case of error, keep empty list — UI shows nothing.
    }
  }

  Future<void> _fetchNextPage() async {
    if (_isFetchingMore || !_hasMore) return;

    setState(() => _isFetchingMore = true);

    try {
      final repository = context.read<CurrencyRepository>();
      final page = await repository.fetchRates(CurrencyPageRequest(
        base: 'USD',
        page: _nextPage,
        pageSize: 20,
      ));

      if (page.items.isNotEmpty) {
        setState(() {
          _allCurrencies.addAll(page.items);
          _nextPage++;
          _hasMore = page.hasMore;
          _filteredCurrenciesNotifier.value = List.unmodifiable(_allCurrencies);
        });
      } else {
        setState(() => _hasMore = false);
      }
    } finally {
      if (mounted) {
        setState(() => _isFetchingMore = false);
      }
    }
  }

  void _filterCurrencies(String query) {
    final String lowerQuery = query.toLowerCase();
    final Iterable<CurrencyModel> result = _allCurrencies.where((currency) {
      return currency.name.toLowerCase().contains(lowerQuery) ||
          currency.symbol.toLowerCase().contains(lowerQuery);
    });

    _filteredCurrenciesNotifier.value = result.toList(growable: false);
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: Text(context.loc.currencyRate)),
      body: ValueListenableBuilder<List<CurrencyModel>>(
        valueListenable: _filteredCurrenciesNotifier,
        builder: (BuildContext context, List<CurrencyModel> data, _) {
          if (data.isEmpty && !_isFetchingMore) return const SizedBox.shrink();

          return FadeTransition(
            opacity: _fadeController.view,
            child: Column(
              children: [
                Padding(
                  padding: const EdgeInsets.symmetric(vertical: 10, horizontal: 22),
                  child: SearchView(onChanged: _filterCurrencies),
                ),
                Expanded(
                  child: ListView.builder(
                    itemCount: data.length,
                    itemBuilder: (BuildContext context, int index) {
                      final CurrencyModel currency = data[index];

                      return Padding(
                        key: ValueKey(currency.id),
